import{_ as t,o as a,c as i,a0 as o}from"./chunks/framework.CShDTZbC.js";const m=JSON.parse('{"title":"Phase 3A: System Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"internals/hackathon-archive/phase-3-architecture.md","filePath":"internals/hackathon-archive/phase-3-architecture.md"}'),n={name:"internals/hackathon-archive/phase-3-architecture.md"};function r(s,e,l,c,h,d){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="phase-3a-system-architecture" tabindex="-1">Phase 3A: System Architecture <a class="header-anchor" href="#phase-3a-system-architecture" aria-label="Permalink to &quot;Phase 3A: System Architecture&quot;">​</a></h1><h2 id="minimum-viable-architecture-mva" tabindex="-1">Minimum Viable Architecture (MVA) <a class="header-anchor" href="#minimum-viable-architecture-mva" aria-label="Permalink to &quot;Minimum Viable Architecture (MVA)&quot;">​</a></h2><p>We have selected <strong>Option C (Single agent with structured tool calling and an external deterministic verifier)</strong>.</p><h3 id="why-option-c" tabindex="-1">Why Option C? <a class="header-anchor" href="#why-option-c" aria-label="Permalink to &quot;Why Option C?&quot;">​</a></h3><p>Phase 2D.5 proved that a single ReAct loop with file/bash capabilities is sufficient to resolve complex local dev failures. Introducing multi-agent hierarchies (e.g., Planner -&gt; Executor -&gt; Verifier) adds immense latency, cost, and debugging complexity without yielding empirical benefits for this specific problem domain. The key is strict deterministic validation, not more LLMs.</p><hr><h2 id="component-design" tabindex="-1">Component Design <a class="header-anchor" href="#component-design" aria-label="Permalink to &quot;Component Design&quot;">​</a></h2><h3 id="_1-user-task-input-the-cli-web-interface" tabindex="-1">1. User/Task Input (The CLI/Web Interface) <a class="header-anchor" href="#_1-user-task-input-the-cli-web-interface" aria-label="Permalink to &quot;1. User/Task Input (The CLI/Web Interface)&quot;">​</a></h3><ul><li><strong>Responsibility:</strong> Accepts the repository path and the broken command from the user (e.g., <code>agentic-troubleshooter --cmd &quot;npm run build&quot;</code>).</li><li><strong>Implementation:</strong> Deterministic CLI entrypoint.</li></ul><h3 id="_2-execution-sandbox-safety-boundary" tabindex="-1">2. Execution Sandbox (Safety Boundary) <a class="header-anchor" href="#_2-execution-sandbox-safety-boundary" aria-label="Permalink to &quot;2. Execution Sandbox (Safety Boundary)&quot;">​</a></h3><ul><li><strong>Responsibility:</strong> Provides an isolated environment where destructive commands cannot harm the host OS.</li><li><strong>Implementation:</strong> Deterministic. The target repository is mounted into a transient Docker container (e.g., <code>ubuntu:latest</code> or matching the dev environment). All agent <code>execute_command</code> tools are routed through <code>docker exec</code>. The container enforces CPU/Memory/Network limits.</li></ul><h3 id="_3-agent-runner-the-controller" tabindex="-1">3. Agent Runner (The Controller) <a class="header-anchor" href="#_3-agent-runner-the-controller" aria-label="Permalink to &quot;3. Agent Runner (The Controller)&quot;">​</a></h3><ul><li><strong>Responsibility:</strong> Manages the <code>while</code> loop, tracks token usage, handles API rate limits, and enforces maximum iterations.</li><li><strong>Inputs:</strong> The conversation history array.</li><li><strong>Outputs:</strong> API requests to the LLM; parsed JSON tool calls.</li><li><strong>Implementation:</strong> Deterministic Python or TypeScript application using official LLM SDKs (e.g., <code>@google/generative-ai</code>).</li></ul><h3 id="_4-the-llm-the-brain" tabindex="-1">4. The LLM (The Brain) <a class="header-anchor" href="#_4-the-llm-the-brain" aria-label="Permalink to &quot;4. The LLM (The Brain)&quot;">​</a></h3><ul><li><strong>Responsibility:</strong> Reads the crash logs, forms hypotheses, and outputs structured tool calls.</li><li><strong>Inputs:</strong> System prompt, user prompt (the crash log), tool responses.</li><li><strong>Outputs:</strong> Text (Thought) + Tool Call (Action).</li><li><strong>Implementation:</strong> Model-driven (Gemini 1.5 Pro).</li></ul><h3 id="_5-independent-verification-engine" tabindex="-1">5. Independent Verification Engine <a class="header-anchor" href="#_5-independent-verification-engine" aria-label="Permalink to &quot;5. Independent Verification Engine&quot;">​</a></h3><ul><li><strong>Responsibility:</strong> Determines objective truth. The LLM is <em>not</em> trusted to declare &quot;I fixed it.&quot;</li><li><strong>Inputs:</strong> The user&#39;s original start command.</li><li><strong>Outputs:</strong> Boolean (Success/Fail) based on Exit Code 0 or a passing health check.</li><li><strong>Implementation:</strong> Deterministic. If the LLM claims victory but the verifier gets Exit 1, the verifier injects: <em>&quot;Verification Failed: The command still errors with [output]. Try again.&quot;</em></li></ul><h3 id="_6-safety-state-manager" tabindex="-1">6. Safety &amp; State Manager <a class="header-anchor" href="#_6-safety-state-manager" aria-label="Permalink to &quot;6. Safety &amp; State Manager&quot;">​</a></h3><ul><li><strong>Responsibility:</strong> Prevents infinite loops and unrecoverable states.</li><li><strong>Implementation:</strong><ul><li><em>Git Snapshotting:</em> Before the agent touches any code, the system runs <code>git init &amp;&amp; git add . &amp;&amp; git commit -m &quot;snapshot&quot;</code>. If the agent ruins the environment, the system runs <code>git reset --hard</code> to rollback.</li><li><em>Command Denylist:</em> Intercepts commands like <code>rm -rf /</code>, <code>sudo</code>, or <code>reboot</code>.</li></ul></li></ul><hr><h2 id="phase-2-to-phase-3-mapping" tabindex="-1">Phase 2 to Phase 3 Mapping <a class="header-anchor" href="#phase-2-to-phase-3-mapping" aria-label="Permalink to &quot;Phase 2 to Phase 3 Mapping&quot;">​</a></h2><ul><li><em>Phase 2D.5 Manual Observation</em> -&gt; Replaced by automated capturing of <code>stdout</code>/<code>stderr</code> from the sandbox.</li><li><em>Phase 2D.5 Antigravity File Editing</em> -&gt; Replaced by LLM <code>patch_file</code> and <code>read_file</code> JSON tool calls.</li><li><em>Phase 2D.5 Iterative Diagnosis</em> -&gt; Replaced by the Agent Runner <code>while</code> loop feeding error logs back to the LLM.</li></ul>',22)])])}const p=t(n,[["render",r]]);export{m as __pageData,p as default};
